/** one object decides; the rules live in a replaceable store behind an interface */
final class ReferenceMonitor {
    private final PolicyStore store;            // no setter, never exposed

    ReferenceMonitor(PolicyStore store) { this.store = store; }

    Decision check(Subject subject, Action action, ObjectId id) {
        if (subject.principal() == null) return Decision.deny("no principal");  // fail closed
        return store.allows(subject, action, id) ? Decision.allow() : Decision.deny("no rule");
    }
}
